package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.NodeVisitor;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.jsoup.select.NodeVisitorImpl;
import org.junit.*;
import org.junit.Test;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.notNullValue;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.matchers.JUnitMatchers.hasItem;

public class Node_previousSibling_TriageGen0Test {

    @Test
    public void testPreviousSibling_EmptyList_returnsNull() {
        // Arrange
        Node node = new Element("test");
        node.parentNode().setChildNodes(new ArrayList<>());
        // Act
        Node previousSibling = node.previousSibling();
        // Assert
        assertNull(previousSibling);
    }

    @Test
    public void testPreviousSibling_SingleElement_returnsNull() {
        // Arrange
        Node node = new Element("test");
        node.parentNode().setChildNodes(new ArrayList<>(List.of(node)));
        // Act
        Node previousSibling = node.previousSibling();
        // Assert
        assertNull(previousSibling);
    }

    @Test
    public void testPreviousSibling_MultipleElements_ReturnsPreviousSibling() {
        // Arrange
        Node node = new Element("test");
        Node sibling = new Element("sibling");
        node.parentNode().setChildNodes(new ArrayList<>(List.of(sibling, node)));
        // Act
        Node previousSibling = node.previousSibling();
        // Assert
        assertEquals(sibling, previousSibling);
    }

    @Test
    public void testPreviousSibling_FirstElement_returnsNull() {
        // Arrange
        Node node = new Element("test");
        Node sibling = new Element("sibling");
        node.parentNode().setChildNodes(new ArrayList<>(List.of(node, sibling)));
        // Act
        Node previousSibling = node.previousSibling();
        // Assert
        assertNull(previousSibling);
    }

    @Test
    public void testPreviousSibling_NullParentNode_throwsNPE() {
        // Arrange
        Node node = new Element("test");
        node.parentNode().setChildNodes(null);
        // Act & Assert
        org.junit.Assert.assertThrows(NullPointerException.class, () -> node.previousSibling());
    }

    @Test
    public void testPreviousSibling_NullChildrenList_throwsNPE() {
        // Arrange
        Node node = new Element("test");
        Node parentNode = new Element("parent");
        parentNode.setChildNodes(null);
        node.parentNode().setChildNodes(parentNode);
        // Act & Assert
        org.junit.Assert.assertThrows(NullPointerException.class, () -> node.previousSibling());
    }

    @Test
    public void testPreviousSibling_ChildNodeIndex_OutOfBounds() {
        // Arrange
        Node node = new Element("test");
        Node sibling = new Element("sibling");
        node.parentNode().setChildNodes(new ArrayList<>(List.of(sibling)));
        // Act
        Node previousSibling = node.previousSibling();
        // Assert
        assertNull(previousSibling);
    }
}
